const items = $input.all();
if (items.length !== 1) throw new Error('Send one GIF search per workflow execution.');
const input = items[0].json;
if (typeof input.query !== 'string') throw new Error('query must be a short search phrase.');
const query = input.query.trim();
if (!query || query.length > 120 || /[\u0000-\u001f\u007f]/.test(query)) {
  throw new Error('query must contain 1–120 characters with no control characters.');
}
const limit = input.limit ?? 3;
if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
  throw new Error('limit must be a whole number from 1 to 10 (default: 3).');
}
// Only these fields reach the HTTP node; do not forward conversation history.
return [{ json: { query, limit } }];

const body = $input.first().json;
const input = $('Validate search').first().json;
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const integer = (value, minimum = 0) => Number.isSafeInteger(value) && value >= minimum;
const mediaUrl = value => typeof value === 'string' && /^https?:\/\/[^\s/@]+(?:[/?#][^\s]*)?$/.test(value);
const invalid = () => { throw new Error('GifSnap returned an invalid response. No GIF was selected.'); };
if (!record(body) || !Array.isArray(body.data) || !record(body.pagination)) invalid();
for (const gif of body.data) {
  if (!record(gif) || typeof gif.id !== 'string' || !gif.id ||
      typeof gif.title !== 'string' || !mediaUrl(gif.url) || !mediaUrl(gif.preview_url) ||
      !integer(gif.width) || !integer(gif.height) || !['gif', 'sticker'].includes(gif.type) ||
      (gif.source !== undefined && typeof gif.source !== 'string') ||
      (gif.content_id !== undefined && (typeof gif.content_id !== 'string' || !gif.content_id.trim()))) invalid();
}
const p = body.pagination;
if (!integer(p.page, 1) || !integer(p.limit, 1) || p.limit > 50 ||
    !integer(p.total) || !integer(p.offset) || typeof p.has_next !== 'boolean' ||
    (p.has_next ? !integer(p.next_page, p.page + 1) : p.next_page !== null)) invalid();
// Keep full media URLs and per-item metadata. Empty results stay empty.
return [{ json: { query: input.query, data: body.data.slice(0, input.limit), pagination: p } }];
